# Homebrew formula for the paxel/tap tap — generated by the release workflow,
# which fills in the tagged version and the sha256 of each release tarball and
# pushes the result to the homebrew-tap repository as Formula/dedup.rb.
# Binary formula: it installs the prebuilt `dedup`.
class Dedup < Formula
  desc "Forensic data-inheritance triage: dedupe, diff and browse file piles"
  homepage "https://github.com/paxel/dedup-rs"
  version "0.1.2"
  license "MIT"

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/paxel/dedup-rs/releases/download/v0.1.2/dedup-0.1.2-macos-arm64.tar.gz"
      sha256 "361ee291909e2b119480afb4edaf0aa8cf621cb4b1024b233737e6da4a96d4d0"
    else
      url "https://github.com/paxel/dedup-rs/releases/download/v0.1.2/dedup-0.1.2-macos-x86_64.tar.gz"
      sha256 "04f47d678ed2d749ce9865cc99844134b1fbd8467b53b0215590e35301e044ab"
    end
  end

  on_linux do
    url "https://github.com/paxel/dedup-rs/releases/download/v0.1.2/dedup-0.1.2-linux-x86_64.tar.gz"
    sha256 "7aff70b8c6f93778b73fd7cd206badec4a5f0c088e0047b4a9ab638788a701ab"
  end

  def install
    bin.install "dedup"
  end

  def caveats
    <<~EOS
      Optional tools unlock extra features (the app works without them):
        ffmpeg       — video previews, filmstrips, soundtrack playback
        poppler      — PDF page rendering (Render tab)
        libreoffice  — office/legacy document page rendering
    EOS
  end

  test do
    system "#{bin}/dedup", "--help"
  end
end
